"Das Bild liegt als Vorlage auf der Ebene. Größe, Lage, Drehung und Deckkraft danach im Eigenschaftenfenster einstellen (z. B. Breite nach einer bekannten Abmessung).":"Slika leži kao predložak na ravni. Veličinu, položaj, rotaciju i neprozirnost zatim podesite u prozoru svojstava (npr. širinu prema poznatoj dimenziji).",
