"Das Netz bleibt ein Dreiecksnetz (kein B-Rep). Bearbeiten unter NETZ: Reparieren, Reduzieren, Glätten, Ebenenschnitt … 3D-Frässtrategien in der Fertigung können es direkt bearbeiten.":"Mreža ostaje trouglasta mreža (nije B-Rep). Uređivanje pod MREŽA: Popravi, Smanji, Zagladi, Presjek ravninom … 3D strategije glodanja u proizvodnji mogu je direktno obrađivati.",
"Das Profil darf die Achse nicht schneiden. Eine offene Linie in der Skizze kann als Achse dienen.":"Profil ne smije presijecati osu. Otvorena linija u skici može poslužiti kao osa.",
"Das Profil mit den jetzigen Werten überschreiben":"Prepisati profil trenutnim vrijednostima",
"Das Profil wird entlang einer Linie/eines Linienzugs geführt. Profil am besten senkrecht zum Pfadanfang zeichnen (z. B. Profil auf XZ, Pfad auf XY).":"Profil se vodi duž linije/polilinije. Profil je najbolje nacrtati okomito na početak putanje (npr. profil na XZ, putanja na XY).",
"Das Profil wird von der Skizzenebene aus erhaben oder vertieft geprägt.":"Profil se utiskuje izdignuto ili udubljeno polazeći od ravni skice.",
"Das Rohteil ist der Quader um den gewählten Körper (plus Versatz).":"Pripremak je kvadar oko odabranog tijela (plus dodatak).",
"Das Setup hat keine Operationen.":"Setup nema operacija.",
"Das Werkzeug fräst in Kreisen, deren Mitte entlang der Nut wandert. Es ist nie über die volle Breite im Eingriff – das erlaubt große Zustelltiefen und schont Fräser und Spindel. Der Fräser sollte etwa 60 % der Nutbreite haben.":"Alat glođe u krugovima čije se središte pomiče duž utora. Nikad nije u zahvatu cijelom širinom – to dopušta velike dubine rezanja i štedi glodalo i vreteno. Glodalo bi trebalo imati oko 60 % širine utora.",
"Das Werkzeug schneidet die Fläche nicht":"Alat ne siječe plohu",
"Das Werkzeug schneidet in Richtung der ausgewählten Flächen, bis es die angegebenen Aufmaße erreicht.":"Alat reže u smjeru odabranih ploha dok ne dosegne zadate dodatke.",
"Das Werkzeug taucht wie ein Bohrer senkrecht ein, Reihe für Reihe, bis auf das Modell plus Aufmaß. Die Schnittkraft wirkt entlang der Spindel: geeignet für lange Werkzeuge, tiefe Kavitäten und wenig steife Maschinen. Das Werkzeug muss über die Mitte schneiden.{0}":"Alat uranja okomito poput svrdla, red po red, do modela plus dodatak. Sila rezanja djeluje duž vretena: pogodno za duge alate, duboke šupljine i manje krute mašine. Alat mora rezati preko središta.{0}",
"Das Werkzeug vermeidet diese Flächen unter Berücksichtigung der angegebenen Sicherheitsabstände (Spanner, Schraubstock).":"Alat izbjegava ove plohe uz poštivanje zadatih sigurnosnih razmaka (stezači, škripac).",
"Das Werkzeug vermeidet diese Flächen, während es in der Nähe liegende Flächen bearbeitet, und hält die Sicherheitsabstände ein.":"Alat izbjegava ove plohe dok obrađuje obližnje plohe i poštuje sigurnosne razmake.",
"Das erste Esc bricht nur das Werkzeug oder die Auswahl ab – ein Esc zu viel schließt die Skizze nicht":"Prvi Esc prekida samo alat ili odabir – višak Esc ne zatvara skicu",
"Das ist keine Bohrung (Verrundung oder Zapfen) – bitte die Innenwand einer Bohrung anklicken.":"Ovo nije rupa (zaobljenje ili čep) – kliknite unutrašnji zid rupe.",
"Das ist keine Bohrung (Zylinderfläche) – bitte die Bohrungswand anklicken.":"Ovo nije rupa (cilindrična ploha) – kliknite zid rupe.",
"Das ist keine WerkFab-Design-Datei.":"Ovo nije datoteka dizajna WerkFab.",
"Das ist keine schräge Kante – beide Enden der Fasenkante anklicken.":"Ovo nije kosa ivica – kliknite na oba kraja ivice skošenja.",
