"Der Durchmesser würde null oder negativ – Abstand verkleinern":"Prečnik bi postao nula ili negativan – smanjite razmak",
"Der Gewindefräser läuft im vollen Material: Den Zapfen vorher freifräsen (2D-Kontur außen um den Zapfen bis zur Gewindetiefe).":"Glodalo za navoje radi u punom materijalu: prethodno oslobodite čep glodanjem (2D kontura izvana oko čepa do dubine navoja).",
"Der Körper hat auf dieser Ebene keinen Umriss.":"Tijelo na ovoj ravni nema obris.",
"Der Körper wird um seine senkrechte Mittelachse abgetastet und als Halterkontur (Abschnitte) in der Dokument-Werkzeugbibliothek gespeichert.":"Tijelo se skenira oko svoje okomite središnje ose i sprema kao kontura držača (segmenti) u biblioteku alata dokumenta.",
"Der Punkt, um den sich die Ansicht dreht (bei freiem Orbit). „Unter dem Mauszeiger“: die Stelle des Modells, an der die Drehung beginnt.":"Tačka oko koje se pogled rotira (kod slobodnog orbita). „Ispod pokazivača miša“: mjesto na modelu na kojem počinje rotacija.",
"Der Radius wächst gleichmäßig vom Anfang zum Ende jeder gewählten Kante. Welches Ende der Anfang ist, legt die Kante fest – bei Bedarf tauschen.":"Polumjer ravnomjerno raste od početka do kraja svake odabrane ivice. Koji je kraj početak određuje ivica – po potrebi zamijenite.",
"Der Rand einer Fläche ist eine geschlossene Kette: Mit „durchlaufend“ läuft der Radius einmal ringsum, ohne diese Option auf jeder Kante für sich vom Anfangs- zum Endradius.":"Rub plohe je zatvoren lanac: s opcijom „neprekidno“ polumjer se mijenja jednom oko cijelog ruba, a bez te opcije na svakoj ivici zasebno od početnog do krajnjeg polumjera.",
"Der Schnitt trifft keinen Körper – es wird kein Material entfernt.":"Rez ne pogađa nijedno tijelo – materijal se ne uklanja.",
"Der Text steht als Kommentar an dieser Stelle im Programm.":"Tekst se nalazi kao komentar na ovom mjestu u programu.",
"Der erste Abstand wird auf der Fläche gemessen, die mehr nach oben (Z) zeigt, der zweite Abstand bzw. der Winkel gilt zur anderen Fläche. „Seiten tauschen“ kehrt das um. Tangential anschließende Kanten laufen mit.":"Prva udaljenost mjeri se na plohi koja je više okrenuta prema gore (Z), druga udaljenost odnosno ugao odnosi se na drugu plohu. „Zamijeni strane“ to obrće. Tangencijalno povezane ivice prate se zajedno.",
"Der gewählte Körper ist das Rohteil (z. B. ein Guss- oder Schmiederohling). Er wird selbst nicht bearbeitet.":"Odabrano tijelo je pripremak (npr. odlivak ili otkivak). Ono samo se ne obrađuje.",
"Der große Geometriekern ist noch nicht geladen":"Veliko geometrijsko jezgro još nije učitano",
"Der große Geometriekern wird geladen – dieser Schritt rechnet gleich von selbst nach":"Veliko geometrijsko jezgro se učitava – ovaj korak će se odmah sam preračunati",
