"Design nicht gefunden.":"Dizajn nije pronađen.",
"Design, Farben, Symbole, Form und Schrift in einer Datei – zum Weitergeben oder für einen anderen Rechner":"Dizajn, boje, simboli, oblik i pismo u jednoj datoteci – za dijeljenje ili za drugo računalo",
