"Die restliche Standzeit reicht nicht für ein Teil – Werkzeug vorher tauschen.":"Preostali vijek trajanja ne dovodi za jedan komad – alat prethodno izmijeniti.",
"Die zweite Komponente muss ein anderer Körper sein.":"Druga komponenta mora biti drugo tijelo.",
