"Eigene Maße und Hinweise lassen sich im Blatt mit der Maus ziehen (Abstand der Maßlinie, Winkel der Hinweislinie, Radius des Winkelbogens). Zwei Ecken anklicken = Längenmaß. Einen Kreisrand in der Draufsicht anklicken = Durchmesser (bzw. Radius). Winkel: erst die Ecke, dann je einen Eckpunkt auf beiden Schenkeln. Fase: beide Enden der schrägen Kante – ergibt z. B. 2×45°. Im Textfeld hinter jedem Maß steht ein Zusatz wie ±0,1, H7 oder 4×.":"Vlastite kote i napomene mogu se na listu povlačiti mišem (razmak kotne linije, ugao linije napomene, radijus ugaonog luka). Klik na dva ugla = linearna kota. Klik na rub kružnice u gornjem pogledu = promjer (odnosno radijus). Ugao: prvo tjeme, zatim po jedna tačka na oba kraka. Skošenje: oba kraja kose ivice – daje npr. 2×45°. U tekstualnom polju iza svake kote nalazi se dodatak poput ±0,1, H7 ili 4×.",
