"Erhebung braucht zwei Skizzen mit geschlossenen Profilen auf verschiedenen Ebenen.":"Loft zahtijeva dvije skice sa zatvorenim profilima na različitim ravnima.",
"Erhebung braucht zwei Skizzen mit je einer Kurve (auf verschiedenen Ebenen).":"Loft zahtijeva dvije skice s po jednom krivuljom (na različitim ravnima).",
"Erhebung nicht möglich – Querschnitte prüfen (je ein geschlossenes Profil, nicht verdreht)":"Loft nije moguć – provjerite poprečne presjeke (po jedan zatvoreni profil, ne uvrnut)",
