"Erst die Fläche an dem Körper anklicken, der bewegt wird, dann die Zielfläche am anderen Körper. Der Körper wird gedreht und verschoben, bis der erste Klickpunkt auf dem zweiten liegt und die Flächen aufeinander liegen.":"Prvo kliknite plohu na tijelu koje se pomjera, zatim ciljnu plohu na drugom tijelu. Tijelo se rotira i pomjera dok prva tačka klika ne leži na drugoj i plohe ne legnu jedna na drugu.",
"Erst die Kante an dem Körper anklicken, der bewegt wird, dann die Zielkante am anderen Körper. Gerade Kanten kommen deckungsgleich aufeinander (Mitte auf Mitte); bei Kreiskanten – Bohrung und Zapfen – werden die Achsen gleich gerichtet und die Mittelpunkte zusammengelegt.":"Prvo kliknite ivicu na tijelu koje se pomjera, zatim ciljnu ivicu na drugom tijelu. Prave ivice se poklapaju (sredina na sredinu); kod kružnih ivica – rupa i čep – ose se usmjeravaju isto i središta se spajaju.",
"Erst ein Setup anlegen.":"Prvo kreirajte setup.",
"Erst ein Setup mit Operationen anlegen.":"Prvo kreirajte setup s operacijama.",
"Erst eine Skizze oder Konstruktionsebene wählen – dann schaut Strg+8 senkrecht darauf.":"Prvo odaberite skicu ili konstrukcijsku ravan – tada Ctrl+8 gleda okomito na nju.",
"Erst einen Körper in KONSTRUKTION erstellen oder ein Netz (STL) einfügen.":"Prvo kreirajte tijelo u KONSTRUKCIJA ili umetnite mrežu (STL).",
