"Fusion-360-Dateien (.f3d) sind ein geschlossenes Autodesk-Format und können nicht gelesen werden.\n\nIn Fusion 360: Datei → Exportieren → STEP (.stp) wählen und diese Datei hier importieren.":"Fusion 360 datoteke (.f3d) su zatvoreni Autodesk format i ne mogu se čitati.\n\nU Fusion 360: odaberite Datoteka → Izvezi → STEP (.stp) i uvezite tu datoteku ovdje.",
