"Für Touchpads: Scrollen verschiebt die Ansicht, Auseinanderziehen (oder Strg + Mausrad) zoomt":"Za touchpade: skrolanje pomjera pogled, razmicanje prstiju (ili Ctrl + kotačić miša) zumira",
