"Für schräge Richtungen eine Konstruktionsachse anlegen (durch zwei Punkte, einen Zylinder oder zwei Ebenen) – sie erscheint dann hier als Richtung.":"Za kose smjerove kreirajte konstrukcijsku osu (kroz dvije tačke, cilindar ili dvije ravni) – ona se tada pojavljuje ovdje kao smjer.",
