"Konturen folgen dem Rand der dunklen Flächen. Die Mittellinie läuft in der Mitte der Striche – passend für Gravuren und Strichzeichnungen. „Geraden, Bögen und Kreise“ erkennt gerade Kanten, scharfe Ecken, Rundungen und Kreise; „Linienzüge“ folgt dem Bild Punkt für Punkt. Den Maßstab danach bei Bedarf mit „Vorlage kalibrieren“ oder „Skalieren“ anpassen.":"Konture prate rub tamnih površina. Središnja linija prolazi sredinom poteza – pogodno za gravure i linijske crteže. „Linije, lukovi i krugovi“ prepoznaje prave ivice, oštre uglove, zaobljenja i krugove; „Polilinije“ prate sliku tačku po tačku. Razmjer zatim po potrebi prilagodite opcijom „Kalibriši predložak“ ili „Skaliraj“.",
