"Kurven":"Krivulje",
"Kurven einer Skizze auf der Planfläche (quer zur Drehachse) mit einem angetriebenen Fräser entlang Z (X und C fahren gemeinsam; Fanuc: Polar-Interpolation G12.1). Offene Kurven werden hin und zurück gefräst. Tiefe ab Planfläche.":"Krivulje skice na čeonoj plohi (poprečno na os rotacije) pogonjenim glodalom duž Z (X i C se kreću zajedno; Fanuc: polarna interpolacija G12.1). Otvorene krivulje glođu se tamo i nazad. Dubina od čeone plohe.",
"Kurven einer Skizze, die längs zur Drehachse liegt, werden auf den Umfang gewickelt und mit einem angetriebenen Fräser gefräst, der zur Achse zeigt (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Die Skizzenebene bestimmt den Winkel, an dem die Kontur sitzt; waagerechte Strecken in der Skizze werden Bögen um das Teil. Tiefe ab Außendurchmesser.":"Krivulje skice koja leži uzdužno uz os rotacije namataju se na obim i glođu pogonjenim glodalom okrenutim prema osi (Z i C se kreću zajedno; Fanuc: cilindrična interpolacija G7.1). Ravan skice određuje ugao na kojem kontura leži; vodoravne dužine u skici postaju lukovi oko dijela. Dubina od vanjskog promjera.",
"Kurzbefehl":"Prečac",
"Kurze Wege (bis zum Halteabstand) fährt das Werkzeug unten im Übergangsvorschub statt über die Rückzugshöhe – ohne Kollisionsprüfung, daher klein halten.":"Kratke putanje (do udaljenosti zadržavanja) alat prelazi dolje prijelaznim posmakom umjesto preko visine povlačenja – bez provjere sudara, zato držite malo.",
