"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Više povezanih ivica računa se kao jedna dionica: polumjer se mijenja od početka lanca do njegovog kraja, kontrolne tačke vrijede u % cijele dužine lanca. To računa veliko geometrijsko jezgro.",
