"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"S kontrolnim tačkama polumjer prolazi kroz zadane vrijednosti (položaj u % dužine ivice). To računa veliko geometrijsko jezgro; prvi put se učitava nekoliko sekundi.",
"Mit dem 3D-Taster kann nicht zerspant werden":"3D sondom se ne može skidati strugotina",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Poređenje s gotovim dijelom: zeleno = na mjeri, plavo = preostali materijal, crveno = predubako",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Mišem preći pored konture (strana određuje smjer) · Esc završava",
"Mit diesem Werkzeug kann nicht gefräst werden":"Ovim alatom se ne može glodati",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"S ureznikom samo ciklus „Urezivanje navoja“ – ciklus bušenja bi ga slomio",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"Uz više prolaza dubina navoja se glođe u koracima koji skidaju otprilike jednaku količinu – štedi male glodala za navoje i tvrde materijale. Prolaz bez podešavanja još jednom prelazi posljednju putanju bez dodatnog koraka.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"Uz „Ciklusi bušenja“ u NC programu izlaze ciklusi upravljanja (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), inače raspisani pokreti.",
