"Noch keine Operation":"Još nema operacije",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"Još nema predložaka. Predložak sprema strategije sa svim postavkama (alat, podaci rezanja, visine, prolazi, povezivanje) za ponovnu upotrebu u drugim setupima i dizajnima.",
