"Nur ASCII-Zeichen":"Samo ASCII znakovi",
"Nur Außenkonturen":"Samo vanjske konture",
"Nur Außenkonturen (Zapfen) gehen als Steuerungszyklus":"Samo vanjske konture (čepovi) mogu kao ciklus upravljanja",
"Nur Durchmesser (Form wie dieses Werkzeug)":"Samo promjer (oblik kao ovaj alat)",
"Nur Innenkonturen (Öffnungen)":"Samo unutrašnje konture (otvori)",
"Nur Rechteck- und Kreistaschen gehen als Steuerungszyklus":"Samo pravougaoni i kružni džepovi mogu kao ciklus upravljanja",
"Nur das bearbeiten, was ein größerer Fräser in Ecken stehen gelassen hat.":"Obrađivati samo ono što je veća glodalica ostavila u uglovima.",
"Nur die Stellen der Kontur nachfahren, die ein größerer Fräser nicht erreicht hat (Innenecken, enge Stellen). Ohne An-/Abfahrbögen, Haltestege und Schlichtdurchgänge; Korrektur im Rechner.":"Prelaziti samo ona mjesta konture koja veća glodalica nije dosegla (unutrašnji uglovi, uska mjesta). Bez ulaznih/izlaznih lukova, držača i prolaza završne obrade; korekcija u računaru.",
"Nur dort, wo das Referenzwerkzeug nicht hinkam: flache Bereiche parallel, steile Bereiche als Wasserlinie. Mit einem Werkzeug aus der Liste zählt dessen Form mit – zum Beispiel was ein Torusfräser in den Hohlkehlen stehen lässt.":"Samo tamo gdje referentni alat nije dospio: ravna područja paralelno, strma područja kao vodena linija. S alatom s popisa računa se i njegov oblik – na primjer ono što torusno glodalo ostavi u žlijebovima.",
"Nur ebene Flächen können als Skizzenebene dienen.":"Samo ravne plohe mogu poslužiti kao ravan skice.",
"Nur ebene Flächen können extrudiert werden":"Samo ravne plohe mogu se ekstrudirati",
"Nur ebene Flächen lassen sich ersetzen":"Samo ravne plohe mogu se zamijeniti",
"Nur ebene Flächen und Zylinderflächen (Bohrungen, Zapfen) lassen sich versetzen":"Samo ravne i cilindrične plohe (rupe, čepovi) mogu se pomjerati",
"Nur ebene Flächen, die nach oben zum Werkzeug zeigen (waagerecht in diesem Setup).":"Samo ravne plohe okrenute prema gore, prema alatu (vodoravne u ovom setupu).",
"Nur für Außen-Drehmeißel":"Samo za vanjske strugarske noževe",
"Nur in Operationen verwendete":"Samo korišteni u operacijama",
"Nur in diesem Projekt":"Samo u ovom projektu",
"Nur mit Korrektur „Im Rechner“.":"Samo s korekcijom „U računaru“.",
"Nur stärkste Achse":"Samo najjača os",
"Nut":"Utor",
"Nut angetrieben":"Pogonjeni utor",
"Nut angetrieben (C-Achse)":"Pogonjeni žlijeb (osa C)",
"Nut liegt nicht am Teil":"Žlijeb nije na dijelu",
"Nut längs der Drehachse (z. B. Passfedernut) mit einem angetriebenen Fräser, der zur Achse zeigt; die Hauptspindel hält das Teil als C-Achse. Nutbreite = Fräser-Ø. Start/Ende Z in Modell-Z; reicht die Nut bis zur Planfläche, fährt der Fräser von vorn ein, sonst taucht er am Start ein. Tiefe ab Außendurchmesser.":"Utor uzduž ose rotacije (npr. utor za klin) pogonjenim glodalom okrenutim prema osi; glavno vreteno drži dio kao C osu. Širina utora = Ø glodala. Početak/kraj Z u Z modela; ako utor seže do čeone plohe, glodalo ulazi sprijeda, inače uranja na početku. Dubina od vanjskog promjera.",
"Nutbreite bei Linien":"Širina utora kod linija",
