"Positiv":"Pozitivno",
"Positiv = nach außen (mehr Material), negativ = nach innen. Ebene Flächen verschieben sich; bei einer Bohrung oder einem Zapfen ändert sich der Radius um den Abstand – eine Bohrung wird mit positivem Abstand enger.":"Pozitivno = prema van (više materijala), negativno = prema unutra. Ravne plohe se pomjeraju; kod rupe ili čepa polumjer se mijenja za iznos udaljenosti – rupa postaje uža s pozitivnom udaljenošću.",
"Positiver Abstand = in Richtung der Skizzennormalen. Taschen: Ausschneiden mit negativem Abstand.":"Pozitivan razmak = u smjeru normale skice. Džepovi: rezanje s negativnim razmakom.",
