"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Namata krivulje skice na cilindar: X ostaje X, udaljenost poprečno na os postaje luk na Ø razvoja (rotacija A). Skica mora ležati paralelno s A osom, npr. na tangencijalnoj ravni. Glođe se na stalnoj dubini ispod površine dijela – za graviranje, natpise i utore oko dijela.",
